<?php require __DIR__.'/private/bootstrap.php';$a=auth();if($a['role']!=='owner'){http_response_code(403);exit('Owner access required.');}$c=config();$message='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();try{$new=$c;foreach(['owner','guest'] as $role){$p=(string)($_POST[$role.'_password']??'');if($p!==''){if(strlen($p)<10||strlen($p)>200)throw new RuntimeException('Passwords need 10–200 characters.');$new[$role.'_hash']=password_hash($p,PASSWORD_DEFAULT);}}$turn=trim($_POST['turn_url']??'');$new['ice_servers']=[['urls'=>'stun:stun.l.google.com:19302']];if($turn!==''){if(!preg_match('/^turns?:[a-zA-Z0-9.\-:\[\]]+(?:\?transport=(?:udp|tcp))?$/D',$turn))throw new RuntimeException('Enter a valid turn: or turns: URL.');$new['ice_servers'][]=['urls'=>$turn,'username'=>cut($_POST['turn_user']??'',150),'credential'=>cut($_POST['turn_password']??'',300)];}$new['revision']=$c['revision']+1;save_config($new);$_SESSION['revision']=$new['revision'];session_write_close();$c=$new;$message='Saved. Friends will need to sign in again; reload the room to apply voice settings.';}catch(Throwable $e){$message=$e->getMessage();}}page_top('Host settings');if($message)echo '<p class="error">'.html($message).'</p>';$turn=$c['ice_servers'][1]??[];?><p><a href="<?=html(base_path())?>/">Back to the room</a></p><form method="post"><input type="hidden" name="csrf" value="<?=html(csrf())?>"><label>New owner password</label><input type="password" name="owner_password" autocomplete="new-password"><label>New guest password</label><input type="password" name="guest_password" autocomplete="new-password"><small>Leave password fields empty to keep them.</small><fieldset><legend>Optional voice relay (TURN)</legend><p>For friends whose networks cannot connect directly. Use credentials from a TURN service you control.</p><label>TURN URL</label><input name="turn_url" placeholder="turns:relay.example.com:5349" value="<?=html($turn['urls']??'')?>"><label>Username</label><input name="turn_user" value="<?=html($turn['username']??'')?>"><label>Credential</label><input type="password" name="turn_password" value="<?=html($turn['credential']??'')?>"><small>Relay credentials are passed to signed-in browsers to make voice calls.</small></fieldset><button>Save host settings</button></form><h2>Storage & backups</h2><p>Private files: <code><?=html($c['storage'])?></code></p><p>Database: <?=html($c['database']['driver'])?>. Back up this private folder and <code>private/config.php</code> together. For MySQL, also export the database.</p><p>Application <?=html(BASEMENT_VERSION)?> · ROM limit 16 GB · chunk size 8 MB</p><?php page_end();?>
